<?php use App\Support\Security;use App\Support\View;$labels=['tournaments'=>['Campeonatos','Organize temporadas, identidade e operação.'],'teams'=>['Equipes','Cadastros e vínculos por projeto.'],'people'=>['Atletas e pessoas','Dados pessoais disponíveis no seu escopo.'],'team_memberships'=>['Comissão técnica','Vínculos de atletas e comissão.'],'registrations'=>['Central de inscrições','Analise e acompanhe a situação das inscrições.'],'documents'=>['Documentos','Arquivos autorizados e sua situação.'],'venues'=>['Locais','Campos e locais operacionais.'],'projects'=>['Projetos','Projetos esportivos da organização.']];[$heading,$description]=$labels[$entity]??[$title,'Gerencie os registros autorizados para seu perfil.'];$navigation=['tournaments'=>'Campeonatos','teams'=>'Equipes','people'=>'Atletas','team_memberships'=>'Comissão','registrations'=>'Inscrições','documents'=>'Documentos','venues'=>'Locais']; ?>
<div class="admin-layout"><button class="drawer-overlay" type="button" data-drawer-close="#admin-navigation" aria-label="Fechar navegação"></button><aside id="admin-navigation" class="sidebar" data-drawer><div class="brand-mark">TG</div><strong>Gestão de Torneios</strong><nav aria-label="Navegação administrativa"><a href="/admin">Visão geral</a><?php foreach($navigation as $key=>$label):?><a class="<?=$entity===$key?'active':''?>" href="/admin/<?=$key?>"><?=View::e($label)?></a><?php endforeach;?></nav><a class="logout" href="/logout">Sair</a></aside><main id="conteudo" class="content management-page"><header class="topbar"><button class="button ghost admin-nav-toggle" type="button" data-drawer-toggle="#admin-navigation" aria-controls="admin-navigation" aria-expanded="false">Menu</button><div><span class="eyebrow">Gestão</span><h1><?=View::e($heading)?></h1><p class="muted"><?=View::e($description)?></p></div><button class="icon-button" data-theme-toggle aria-label="Alternar tema" aria-pressed="false">◐</button></header><div class="management-actions"><a class="button" href="#formulario">Adicionar registro</a><?php if($entity==='documents'):?><a class="button ghost" href="/admin/documents/upload">Enviar documento</a><?php endif;?></div><section id="formulario" class="panel management-form"><div class="panel-head"><div><span class="eyebrow"><?=isset($editing)?'Edição':'Novo registro'?></span><h2><?=isset($editing)?'Atualize os dados':'Informações principais'?></h2></div></div><form method="post" action="/admin/<?=$entity?>/save"><input type="hidden" name="_csrf" value="<?=View::e(Security::csrfToken())?>"><input type="hidden" name="id" value="<?=View::e($editing['id']??'')?>"><div class="form-grid"><?php foreach($meta['fields'] as $field):?><label><?=View::e(ucwords(str_replace('_',' ',$field)))?><input name="<?=View::e($field)?>" value="<?=View::e($editing[$field]??'')?>"></label><?php endforeach;?></div><div class="form-actions"><button class="button primary" type="submit"><?=isset($editing)?'Salvar alterações':'Adicionar registro'?></button><?php if(isset($editing)):?><a class="button ghost" href="/admin/<?=$entity?>">Cancelar</a><?php endif;?></div></form></section><section class="panel management-list"><div class="panel-head"><div><span class="eyebrow">Registros</span><h2><?=$pager['total']??count($rows)?> encontrados</h2></div><div class="view-toggle"><button type="button" class="button ghost" data-view-toggle="table">Tabela</button><button type="button" class="button ghost" data-view-toggle="cards">Cards</button></div></div><form class="filter-bar" method="get" action="/admin/<?=$entity?>"><label class="sr-only" for="buscar">Buscar</label><input id="buscar" name="q" value="<?=View::e($query??'')?>" placeholder="Buscar por dados disponíveis"><button class="button" type="submit">Buscar</button><?php if(($query??'')!==''):?><a class="button ghost" href="/admin/<?=$entity?>">Limpar filtros</a><span class="badge">Filtro ativo</span><?php endif;?></form><?php if(!$rows):?><div class="empty"><strong>Nenhum registro encontrado.</strong><br>Revise os filtros ou adicione o primeiro registro.</div><?php else:?><div class="table-wrap management-table" data-management-view="table"><table><thead><tr><?php foreach(array_keys($rows[0]) as $column):if(in_array($column,['deleted_at','created_at','updated_at'],true))continue;?><th><?=View::e(ucwords(str_replace('_',' ',$column)))?></th><?php endforeach;?><th>Ações</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach($row as $column=>$value):if(in_array($column,['deleted_at','created_at','updated_at'],true))continue;?><td><?=View::e((string)$value)?></td><?php endforeach;?><td class="row-actions"><?php if($entity==='documents'):?><a class="link" href="/admin/documents/<?=$row['id']?>/download">Baixar</a><?php endif;?><a class="link" href="/admin/<?=$entity?>/<?=$row['id']?>">Editar</a><form method="post" action="/admin/<?=$entity?>/delete" data-confirm="Remover este registro?"><input type="hidden" name="_csrf" value="<?=View::e(Security::csrfToken())?>"><input type="hidden" name="id" value="<?=$row['id']?>"><button class="link danger" type="submit">Remover</button></form></td></tr><?php endforeach;?></tbody></table></div><div class="management-cards" data-management-view="cards" hidden><?php foreach($rows as $row):?><article class="card"><strong><?=View::e($row['name']??$row['full_name']??$row['title']??('Registro #'.$row['id']))?></strong><span class="status"><?=View::e($row['status']??'ativo')?></span><p class="muted"><?=View::e($row['short_name']??$row['public_name']??$row['description']??'Informações disponíveis para este registro.')?></p><a class="link" href="/admin/<?=$entity?>/<?=$row['id']?>">Abrir detalhes</a></article><?php endforeach;?></div><?php if(($pager['pages']??1)>1):?><nav class="pagination" aria-label="Paginação"><?php for($p=1;$p<=$pager['pages'];$p++):?><a class="button <?=$p===($pager['page']??1)?'primary':'ghost'?>" href="/admin/<?=$entity?>?page=<?=$p?>&q=<?=urlencode($query??'')?>"><?=$p?></a><?php endfor;?></nav><?php endif;?><?php endif;?></section></main></div>
